eito, as cores, o brilho e os dispositivos anteriores serão recuperados.</p><div class=config-actions><button class=config-cancel>Cancelar</button><button class=power-restore-button>Restaurar luzes</button></div>':'<div class=power-icon>◉</div><h3>Apagar todas as luzes?</h3><p>O teclado, gabinete, placa de vídeo e memórias serão apagados. Você poderá restaurar depois.</p><div class=config-actions><button class=config-cancel>Cancelar</button><button class=power-confirm-button>Apagar luzes</button></div>';function close(){modal.remove()}box.querySelector('.config-cancel').onclick=close;box.querySelector(restore?'.power-restore-button':'.power-confirm-button').onclick=function(){close();togglePower()};modal.onclick=function(e){if(e.target==modal)close()};document.body.appendChild(modal)}power.onclick=confirmPower;document.addEventListener('click',function(e){if(!remote||!remote.blackout)return;if(e.target.closest('#powerTool')||e.target.closest('.preset-modal'))return;e.preventDefault();e.stopImmediatePropagation();showLocked()},true);var originalDevices=document.querySelector('#devices').closest('section');originalDevices.style.display='none';var rigs=wrap.querySelectorAll('.rig-card');for(let i=0;i<rigs.length;i++)rigs[i].onclick=function(){remote.devices[i].enabled=!remote.devices[i].enabled;markDirty();drawRigs();var ids=remote.devices.filter(function(d){return d.enabled}).map(function(d){return d.index}).join(',');fetch('/set?color='+encodeURIComponent(remote.color)+'&mode='+remote.mode+'&brightness='+remote.brightness+'&devices='+ids)}})()</script>";byte[] bytes=Encoding.UTF8.GetBytes(body);string headers="HTTP/1.1 "+status+" OK\r\nContent-Type: "+type+"\r\nCache-Control: no-store, no-cache, must-revalidate\r\nContent-Length: "+bytes.Length+"\r\nConnection: close\r\n\r\n";byte[] head=Encoding.ASCII.GetBytes(headers);stream.Write(head,0,head.Length);stream.Write(bytes,0,bytes.Length);}
 string MobilePage(){return @"<!doctype html><meta name='viewport' content='width=device-width,initial-scale=1'><style>@import url(\'https://fonts.googleapis.com/css2?family=JetBrains+Mono:wght@400;500;600;700&display=swap\');html{background:#0d0f18}body{margin:0;min-height:100vh;padding:24px;background:radial-gradient(circle at 15% 0,#49368a 0,transparent 35%),linear-gradient(145deg,#0d0f18,#171224 58%,#0c1220) fixed no-repeat;background-size:cover;color:#fff;font:15px 'JetBrains Mono',Consolas,monospace}main{max-width:430px;margin:auto}.brand{color:#c5b7ff;font-size:12px;font-weight:bold;letter-spacing:1px}.brand b{display:block;color:#fff;font-size:26px;margin-top:5px}.card{background:#1a1c2acc;border:1px solid #ffffff14;border-radius:20px;padding:17px;margin-top:16px}.color-preview{margin-top:16px;min-height:78px;box-sizing:border-box;border-radius:20px;padding:14px;position:relative;overflow:hidden;background:linear-gradient(135deg,#a880ff,#6b3fff 45%,#361b7c)}.color-preview:after{content:\'\';position:absolute;width:150px;height:150px;border-radius:50%;background:#ffffff23;right:-55px;top:-58px}.color-preview b{display:block;font-size:21px;margin-top:5px;position:relative;z-index:1}.color-dot{position:absolute;right:18px;bottom:15px;width:33px;height:33px;border-radius:50%;background:#fff;border:4px solid #ffffffa8;z-index:2}.quick-title{margin-top:19px}.cap{color:#aaa6bd;font-size:11px;font-weight:bold;letter-spacing:1px}.field{width:100%;height:47px;margin-top:9px;box-sizing:border-box;padding:10px;border:1px solid #ffffff18;border-radius:12px;background:#10121c;color:#fff;font:inherit}.colors,.devices{display:grid;grid-template-columns:repeat(3,1fr);gap:9px;margin-top:12px}.colors{grid-template-columns:repeat(6,minmax(0,1fr));gap:10px}.colors button{max-width:38px;justify-self:center;width:100%;height:auto;aspect-ratio:1;border:0;border-radius:50%;font-size:0;background:#fff;box-shadow:inset 0 0 0 1px #ffffff28}.colors button.on{outline:3px solid #d3c1ff;outline-offset:3px}.bright-row{display:flex;align-items:center;gap:10px;margin-top:17px;color:#d9d1eb}.bright-row input{margin:0;flex:1}.bright-row input:disabled{opacity:.38;filter:grayscale(1);cursor:not-allowed}.bright-row b{font-size:13px;color:#fff}.effect-card{height:58px;border-radius:15px;margin-top:8px;padding:0 12px;display:flex;align-items:center;gap:10px}.effect-icon{width:32px;height:32px;border-radius:10px;background:#8d63f5;display:grid;place-items:center;font-style:normal;font-size:17px}.effect-copy{display:flex;flex-direction:column;gap:2px}.effect-copy b{font-size:14px}.effect-copy small{color:#aaa6bd;font-size:11px}.effect-select{margin-left:auto;width:28px;height:100%;border:0;background:transparent;color:transparent;font-size:0;outline:0}.devices{grid-template-columns:repeat(2,1fr)}.device{padding:12px;text-align:left;color:#fff;border:1px solid #ffffff16;border-radius:12px;background:#10121c}.device.on{background:#30234d;border-color:#a184ff}.device small{display:block;color:#aaa6bd;margin-top:3px}.apply{width:100%;height:52px;margin-top:15px;border:0;border-radius:14px;background:linear-gradient(105deg,#b192ff,#7654e8);color:#171122;font-weight:900}.secondary{width:100%;height:42px;margin-top:9px;background:#ffffff12;border:1px solid #ffffff20;border-radius:12px;color:#fff}.status,.note{color:#aaa6bd;margin-top:14px}.dot{display:inline-block;width:8px;height:8px;border-radius:9px;background:#49d796;margin-right:8px}</style><main><header class='brand'><span class='brand-kicker'>THEBESTRGB <i></i> ONLINE</span><b>Controle do setup</b><small>Iluminação remota · Rede local</small></header><section class='color-preview'><div class='cap'>COR ATUAL</div><b id='colorName'>Branco puro</b><i id='colorDot' class='color-dot'></i></section><section class='card'><div id='quickColorsBlock'><div class='cap quick-title'>CORES RÁPIDAS</div><div class='colors'><button class='on' onclick='quick(&quot;ffffff&quot;,&quot;Branco puro&quot;,this)'>Branco</button><button style='background:#e84657' onclick='quick(&quot;ff304b&quot;,&quot;Vermelho intenso&quot;,this)'>Vermelho</button><button style='background:#3f9df5' onclick='quick(&quot;4bb8ff&quot;,&quot;Azul elétrico&quot;,this)'>Azul</button><button style='background:#28ba7d' onclick='quick(&quot;20e497&quot;,&quot;Verde neon&quot;,this)'>Verde</button><button style='background:#8758e9' onclick='quick(&quot;a060ff&quot;,&quot;Roxo&quot;,this)'>Roxo</button><button style='background:#ee9838' onclick='quick(&quot;ff9b38&quot;,&quot;Laranja&quot;,this)'>Laranja</button></div></div><div class='bright-row'><span>Brilho</span><input id='brightness' type='range' min='0' max='100'><b id='brightnessLabel'>100%</b></div><div class='bright-row'><span>Velocidade</span><input id='speed' type='range' min='1' max='5'><b id='speedLabel'>3 / 5</b></div><input id='color' type='hidden'><div class='cap quick-title'>EFEITO</div><div id='effectTool' class='field effect-card'><i class='effect-icon'>✦</i><div class='effect-copy'><b id='effectName'>Cor fixa</b><small id='effectDesc'>Uma cor uniforme no setup</small></div><select id='mode' class='effect-select'><option value='0'>Cor fixa</option><option value='1'>Arco-íris</option><option value='2'>Respiração</option><option value='3'>Rainbow</option><option value='4'>Onda pelo setup</option><option value='5'>Passagem de luz</option><option value='6'>Aurora</option><option value='7'>Oceano</option><option value='8'>Fogo</option><option value='9'>Pôr do sol</option><option value='10'>Neon</option><option value='11'>Pastel</option><option value='12'>Batimento</option><option value='13'>Vela</option><option value='14'>Respiração alternada</option><option value='15'>Duas cores</option><option value='16'>Elétrica</option><option value='17'>Áudio</option><option value='18'>Ambilight</option></select></div><button class='apply' onclick='apply()'>Aplicar iluminação</button></section><section class='card'><div class='cap'>DISPOSITIVOS</div><div id='devices' class='devices'></div><button class='apply' onclick='apply()'>Aplicar selecionados</button><button class='secondary' onclick='fetch(&quot;/stop&quot;)'>Parar efeito</button><div id='note' class='note'></div></section><section class='card'><div class='cap'>PERFIS SALVOS</div><div id='profiles'></div></section><div class='status'><i class='dot'></i>Conectado ao ThebestRGB neste PC</div></main><script>let state;var effectLabels=['Cor fixa','Arco-íris','Respiração','Rainbow','Onda pelo setup','Passagem de luz','Aurora','Oceano','Fogo','Pôr do sol','Neon','Pastel','Batimento','Vela','Respiração alternada','Duas cores','Elétrica','Áudio','Ambilight'];function showColor(name,value,button){document.getElementById('colorName').textContent=name||value;document.getElementById('colorDot').style.background=value;var dots=document.querySelectorAll('.colors button'),known=['#ffffff','#ff304b','#4bb8ff','#20e497','#a060ff','#ff9b38'];dots.forEach(function(b,i){b.classList.toggle('on',button?b===button:known[i].toLowerCase()==value.toLowerCase())})}function showEffect(){var m=document.getElementById('mode');document.getElementById('effectName').textContent=effectLabels[m.value];document.getElementById('effectDesc').textContent=m.value==0?'Uma cor uniforme no setup':'Toque para escolher outro efeito';document.getElementById('quickColorsBlock').style.display=m.value==0?'block':'none';var configButton=document.getElementById('effectConfigTool');if(configButton)configButton.style.display=m.value==0?'none':'block'}async function load(){state=await fetch('/state').then(function(x){return x.json()});document.getElementById('color').value=state.color;document.getElementById('brightness').value=state.brightness;syncBrightness(state.brightness);document.getElementById('speed').value=state.effect.speed;document.getElementById('speedLabel').textContent=state.effect.speed+' / 5';document.getElementById('mode').value=state.mode;showColor('',state.color);showEffect();draw()}function draw(){var devices=document.getElementById('devices'),profiles=document.getElementById('profiles');devices.innerHTML=state.devices.map(function(d){return `<button class='device ${d.enabled?'on':''}' onclick='state.devices[${d.index}].enabled=!state.devices[${d.index}].enabled;draw()'><b>${d.enabled?'✓':'○'} ${d.name}</b><small>Brilho ${d.brightness}%</small></button>`}).join('');profiles.innerHTML=state.profiles.map(function(p){return `<button class='secondary' onclick='profile(${p.index})'>${p.name}</button>`}).join('')||'<div class=note>Nenhum perfil salvo.</div>'}function quick(c,name,button){if(remote&&remote.blackout){showLocked();return}document.getElementById('mode').value=0;showEffect();document.getElementById('color').value='#'+c;showColor(name,'#'+c,button);apply()}function apply(){if(remote&&remote.blackout){showLocked();return}var note=document.getElementById('note'),color=document.getElementById('color'),mode=document.getElementById('mode'),brightness=document.getElementById('brightness');note.textContent='Aplicando…';fetch('/set?color='+encodeURIComponent(color.value)+'&mode='+mode.value+'&brightness='+brightness.value+'&speed='+document.getElementById('speed').value).then(function(){panelDirty=false;note.textContent='Iluminação aplicada.';panelStatus('● Iluminação aplicada','applied')})}function syncBrightness(value){var n=Math.max(0,Math.min(100,Number(value)||0));document.getElementById('brightness').value=n;document.getElementById('brightnessLabel').textContent=n+'%'}function changedBrightness(){if(typeof markDirty==='function'&&!markDirty())return;syncBrightness(this.value);var automatic=document.getElementById('autoSwitch');if(automatic&&automatic.checked){clearTimeout(window.mobileBrightnessTimer);window.mobileBrightnessTimer=setTimeout(apply,160)}}document.getElementById('brightness').addEventListener('input',changedBrightness);document.getElementById('brightness').addEventListener('change',changedBrightness);document.getElementById('speed').oninput=function(){if(!markDirty())return;document.getElementById('speedLabel').textContent=this.value+' / 5';var automatic=document.getElementById('autoSwitch');if(automatic&&automatic.checked){clearTimeout(window.mobileSpeedTimer);window.mobileSpeedTimer=setTimeout(apply,160)}};document.getElementById('mode').onchange=function(){if(!markDirty())return;showEffect()};function profile(i){fetch('/profile?index='+i).then(function(){document.getElementById('note').textContent='Perfil aplicado.';setTimeout(load,400)})}load()</script>";}
 void ShowMobileRemote(){if(string.IsNullOrEmpty(mobileAddress)){MessageBox.Show(this,"Não foi possível iniciar o controle pelo celular nesta rede.","ThebestRGB");return;}using(var dialog=new Form{Text="ThebestRGB / Controle pelo celular",ClientSize=new Size(510,218),BackColor=surface,ForeColor=Color.White,Font=new Font("Segoe UI",10),StartPosition=FormStartPosition.CenterParent,MaximizeBox=false,MinimizeBox=false}){dialog.Controls.Add(new Label{Text="No celular, conectado ao mesmo Wi-Fi, abra:",AutoSize=true,Location=new Point(24,34)});var address=new TextBox{ReadOnly=true,Multiline=true,Text=mobileAddress,BackColor=Color.FromArgb(35,38,50),ForeColor=Color.White,BorderStyle=BorderStyle.FixedSingle};address.SetBounds(24,65,462,50);dialog.Controls.Add(address);dialog.Controls.Add(new Label{Text="Funciona somente nesta rede. Mantenha o ThebestRGB aberto neste PC.",ForeColor=Muted,Size=new Size(462,28),Location=new Point(26,128)});var close=Button("Fechar",surface);close.DialogResult=DialogResult.OK;close.SetBounds(356,170,130,32);dialog.Controls.Add(close);dialog.AcceptButton=close;DarkDialogChrome.Attach(dialog,dialog.Text);dialog.ShowDialog(this);}}
